import{j as e}from"./index-B_pXcd0Z.js";import"./vendor-nf7bT_Uh.js";const i={slug:"ai-pitch-short",eyebrow:"Guidepoint · CRM Next · Q1–Q2 2025",title:"AI Advisor Pitches",standfirst:"Clients pick whoever puts a credible advisor list in front of them first. Competitors answered in fifteen minutes; we took an hour, and almost all of it was project managers writing pitches by hand.",hero:{type:"video",src:"/AI-mock.mp4",alt:"The AI summary builder in use"},facts:[{label:"Role",value:"Lead designer & researcher"},{label:"Platform",value:"Desktop web · internal CRM"},{label:"Timeline",value:"Q1–Q2 2025"},{label:"Status",value:"Shipped to beta"}],outcomes:[{value:"4×",label:"Faster pitch turnaround",detail:"40–60 minutes down to under 10."},{value:"100%",label:"Drop in clients lost to speed",detail:"In the unvetted advisor flow."},{value:"250",label:"Project managers on early release",detail:"Across every industry vertical."}],chapters:[{id:"problem",phase:"Situation",kicker:"Problem statement",mark:"aiSpeed",title:"Competitors answered in 15 minutes. We took an hour.",lede:"Nearly all of the lag sat in one step: a project manager writing a summary arguing each advisor’s fit, by hand, one advisor at a time. Ten PMs had seven ways of writing the same thing, so quality moved with whoever picked up the request.",media:[{type:"image",src:"/ex-summ.png",alt:"A hand-written advisor summary as it existed before",layout:"wide",caption:"What a pitch looked like when a person wrote every one of them."}]},{id:"brief",phase:"Task",kicker:"The brief",title:"How might we cut the hour between a client asking and a credible advisor list landing, without losing the argument that wins the project?",lede:"Speed was the whole business problem, so this was a time budget before it was a design brief."},{id:"discovery",phase:"Action",kicker:"Discovery · 10 project managers",title:"Ten PMs, seven ways of writing the same thing.",lede:"Before the model could have a house style I had to establish what a good summary even was. The split that mattered was unvetted profiles, before screening, against vetted ones.",media:[{type:"image",src:"/summaryscale.png",alt:"Summary styles mapped from brief to detailed",layout:"wide",caption:"Summary styles mapped end to end. The baseline the model output had to hit."}],flowCompare:{lanes:[{label:"Vetted",sub:"the basic path",steps:[{t:"Client"},{t:"Brief"},{t:"PM"},{t:"Finds advisors"},{t:"Sends screeners",tone:"screen",note:"Screening happens before the client sees anyone."},{t:"Advisors respond",tone:"screen",note:"Fresh, project-specific answers exist by the time the list goes out."},{t:"Advisor sent to client",tone:"client",note:"Arrives pre-qualified, and two steps later than the fast path."},{t:"Client selects",tone:"client",note:"Choosing from an already-screened shortlist."},{t:"Consult"}]},{label:"Unvetted",sub:"the fast path",emphasis:!0,steps:[{t:"Client"},{t:"Brief"},{t:"PM"},{t:"Finds advisors"},{t:"Advisor sent to client",tone:"client",note:"Reaches the client with no project-specific screener behind them. This is the whole time saving."},{t:"Client selects",tone:"client",note:"Chooses on past screener answers and profile alone, which is all the summary has to argue from."},{t:"Sends screeners",tone:"screen",note:"If they are sent at all. Sometimes bypassed entirely."},{t:"Advisors respond",tone:"screen",note:"Where the advisor expresses interest in the project. The client has already picked them, so responding is opting in rather than qualifying for a shortlist."},{t:"Consult"}]}],key:[{tone:"screen",label:"Screening"},{tone:"client",label:"In front of the client"}],note:"Unvetted is what makes a quick turnaround possible: the advisor reaches the client before any project-specific screener has been sent. Past relevant screening answers stand in for fresh ones, and sometimes no project screener is sent at all. Which is exactly why the model had least to work with on unvetted profiles, and why that became the case worth solving."}},{id:"testing",phase:"Action",navLabel:"Usability testing",kicker:"Usability testing · 7 project managers",title:"Two layouts. The one that won treated AI as a first draft.",lede:"A light-touch revision against a full rebuild. The rebuild won because it gave the editor the room. A summary is something you correct, not something you compose.",media:[{type:"image",src:"/ai-summ-UT.png",alt:"The two tested layouts side by side",layout:"wide",caption:"Option A kept the old shell. Option B rebuilt around editing."}],deepDive:{label:"What testing surfaced",static:!0,body:e.jsxs("div",{className:"dd-cols",children:[e.jsxs("div",{className:"dd-col",children:[e.jsx("h3",{className:"dd-col-h is-pos",children:"Option B: what won it"}),e.jsxs("ul",{children:[e.jsx("li",{children:"The layout promotes editing; advisor detail stays visible but secondary."}),e.jsx("li",{children:"Summary and email composer in one step."}),e.jsx("li",{children:"Translation surfaced instead of buried."}),e.jsx("li",{children:"LinkedIn reachable for cross-checking job history."})]})]}),e.jsxs("div",{className:"dd-col",children:[e.jsx("h3",{className:"dd-col-h is-neg",children:"Option A: what lost it"}),e.jsxs("ul",{children:[e.jsx("li",{children:"Auto-generating on load was killed, in favor of an explicit generate action."}),e.jsx("li",{children:"The bulk dropdown was not discoverable."}),e.jsx("li",{children:"Too little room to review what the model produced."}),e.jsx("li",{children:"Translation hidden at the top of the window."}),e.jsx("li",{children:"No advisor count in the builder, true of both options."})]})]}),e.jsxs("div",{className:"dd-col",children:[e.jsx("h3",{className:"dd-col-h is-pos",children:"Why stakeholders agreed"}),e.jsxs("ul",{children:[e.jsx("li",{children:"A branded generate button drives AI adoption."}),e.jsx("li",{children:"It shifts the mental model from building to editing."}),e.jsx("li",{children:"Merging the composer removes a whole step from the send."})]})]})]})}},{id:"workshop",phase:"Action",navLabel:"Model workshop",kicker:"Model workshop · 10 PMs across verticals",title:"The model was confident and wrong about unvetted advisors.",lede:"Vetted summaries came back consistently good. Unvetted ones claimed no data existed, while the API was passing matched screeners with confidence scores that the front end was filtering out.",steps:[{n:"Heard",title:"Trust comes before polish",note:"Accuracy is what reduces manual edits over time. Repetition of names and titles reads as machine-written, and one wrong claim costs more than a dull sentence."},{n:"Changed",title:"Weight recent screeners, and show the reasoning",note:"Fixed the “no data” error, surfaced the confidence-score reasoning, and kept the advisor’s key data visible to the PM throughout."}]},{id:"shipped",phase:"Result",kicker:"What shipped to beta",title:"Four changes, each removing a manual step.",lede:"Each one replaces a step a project manager used to do by hand, somewhere between “client asks” and “client has a list”.",gallery:[{type:"image",src:"/ai-layout.png",alt:"The rebuilt summary editing layout",title:"A layout that promotes editing",swap:{from:"Composing each summary from a blank field",to:"Correcting a draft, detail on demand"},note:"The editor takes the space; per-advisor detail steps back."},{type:"video",src:"/ai-toolbar.mp4",alt:"The bulk action toolbar",title:"Bulk action toolbar",swap:{from:"Generating and approving one advisor at a time",to:"The whole shortlist in one pass"},note:"Generate, regenerate and approve across a whole shortlist rather than one advisor at a time."},{type:"video",src:"/ai-rewrite.mp4",alt:"Rewriting a single summary",title:"Rewrite one at a time",swap:{from:"Regenerating the set to fix one bad summary",to:"Rewriting only the one that came back wrong"},note:"The bulk pass gets it close; this is how a PM fixes the one that came back wrong."},{type:"image",src:"/ai-email.png",alt:"The summary builder and the client email composer in one place",title:"Compose and send in one place",swap:{from:"Leaving the builder to write the client email",to:"Summaries and email living together"},note:"The email composer moved into the builder, so two steps became one. It loads only once every advisor pitch has been approved, so the send is gated on the work being finished rather than on the PM remembering to check."}]},{id:"impact",phase:"Result",kicker:"Impact",title:"An hour down to less than ten minutes.",media:[{type:"video",src:"/summ-mock.mp4",alt:"The AI summary builder generating and editing pitches",layout:"wide",caption:"The pass a PM makes now: generate across the shortlist, correct what came back wrong, send."}],steps:[{n:"01",title:"The model drafts, the PM judges",note:"That split is what bought the time back. It did not remove the argument that wins the project. It removed the typing."},{n:"02",title:"Consistency stopped depending on who picked it up",note:"Seven ways of writing the same thing became one house style with a person correcting it, so quality no longer moved with the assignee."}]}],closing:"What began as a response to competitive pressure ended up resetting how the CRM treats writing: the model drafts, the PM judges.",longRead:{to:"/case-study/AIsummary",note:"The long version carries the seven PM archetypes in full, the complete model workshop, and the wider four-step flow the summaries sit inside."}};export{i as default};
